import json

def format_card(c_id, category, mod_code, mod_name, diff, f_title, f_prompt, b_title, b_content, rfc=None, cli=None, hint=""):
    c = {
        "id": c_id,
        "category": category,
        "moduleCode": mod_code,
        "moduleName": mod_name,
        "difficulty": diff,
        "frontTitle": f_title,
        "frontPrompt": f_prompt,
        "backTitle": b_title,
        "backContent": b_content,
        "hint": hint
    }
    if rfc:
        c["rfcRef"] = rfc
    if cli:
        c["cliExample"] = cli
    return c

